func (q *Queries) UpsertInjuryGroupMember(ctx context.Context, arg UpsertInjuryGroupMemberParams) (InjuryGroupMember, error) {
	row := q.db.QueryRow(ctx, upsertInjuryGroupMember,
		arg.UserID,
		arg.BodyPart,
		arg.InjuredOn,
		arg.Diagnosis,
		arg.Severity,
		arg.SawDoctor,
		arg.Place,
		arg.Activity,
		arg.PreChanges,
		arg.Event,
		arg.Stage,
	)
	var i InjuryGroupMember
	err := row.Scan(
		&i.UserID,
		&i.BodyPart,
		&i.InjuredOn,
		&i.PlaceNote,
		&i.SituationNote,
		&i.Stage,
		&i.JoinedAt,
		&i.UpdatedAt,
		&i.Diagnosis,
		&i.Severity,
		&i.SawDoctor,
		&i.Place,
		&i.Activity,
		&i.PreChanges,
		&i.Event,
	)
	return i, err
}
